class BusinessDate:
    def __init__(self, value, holiday_calendar):
        self._value = value
        self._holiday_calendar = holiday_calendar

    def is_working_day(self):
        is_weekend = self._value.weekday() >= 5
        return not is_weekend and not self._holiday_calendar.contains(self._value)

    def next_working_day(self):
        candidate = BusinessDate(
            self._value + timedelta(days=1),
            self._holiday_calendar,
        )
        while not candidate.is_working_day():
            candidate = BusinessDate(
                candidate._value + timedelta(days=1),
                self._holiday_calendar,
            )
        return candidate

